export interface ConnectorConfig {
  /** The S3 presign endpoint URL (POST to this with Key and ContentType to get a presigned PUT URL). */
  s3PresignUrl: string;
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX). */
  airtableBaseId: string;
  /** Airtable table ID or name (e.g., tblXXXXXXXXXXXXXX or "Table 1"). */
  airtableTableId: string;
  /** Airtable record ID to update (e.g., recXXXXXXXXXXXXXX). Can be a string or a function to resolve from payload. */
  airtableRecordId: string | ((payload: TypeformPayload) => string);
  /** Airtable API key (from env var AIRTABLE_API_KEY). */
  airtableApiKey: string;
  /** Injected fetch for testing. */
  fetch?: typeof fetch;
}

export interface TypeformAnswer {
  type: string;
  file_url?: string;
  field: {
    id: string;
    type: string;
  };
}

export interface TypeformFormResponse {
  form_id: string;
  token: string;
  submitted_at: string;
  answers: TypeformAnswer[];
}

export interface TypeformPayload {
  event_id: string;
  event_type: string;
  form_response: TypeformFormResponse;
}

export interface S3PresignRequest {
  Key: string;
  ContentType: string;
}

export interface S3PresignResponse {
  url: string;
  fields: Record<string, string>;
}

export interface AirtableAttachment {
  url: string;
  filename?: string;
}

export interface AirtableUpdateRequest {
  fields: {
    "File Attachment": AirtableAttachment[];
  };
}

export interface AirtableUpdateResponse {
  id: string;
  fields: {
    "File Attachment": Array<AirtableAttachment & { id: string }>;
  };
}

export interface HandleResult {
  s3PresignedUrl: string;
  s3PublicUrl: string;
  airtableRecordId: string;
  airtableAttachmentIds: string[];
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch;
}

function extractFirstFileAnswer(payload: TypeformPayload): TypeformAnswer {
  const fileAnswer = payload.form_response.answers.find(
    (a) => a.type === "file_url" && a.file_url
  );
  if (!fileAnswer) {
    throw new Error("No file_url answer found in Typeform payload");
  }
  return fileAnswer;
}

function deriveKeyAndContentType(fileUrl: string): { key: string; contentType: string } {
  const url = new URL(fileUrl);
  const pathname = url.pathname.replace(/^\/+/, "");
  const filename = pathname.split("/").pop() || "upload";
  const ext = filename.split(".").pop()?.toLowerCase() || "";
  const contentTypeMap: Record<string, string> = {
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    png: "image/png",
    gif: "image/gif",
    pdf: "application/pdf",
    txt: "text/plain",
    csv: "text/csv",
    json: "application/json",
  };
  const contentType = contentTypeMap[ext] || "application/octet-stream";
  const key = `uploads/${Date.now()}-${filename}`;
  return { key, contentType };
}

async function downloadFile(url: string, fetchFn: typeof fetch): Promise<{ blob: Blob; contentType: string }> {
  const resp = await fetchFn(url);
  if (!resp.ok) {
    throw new Error(`Failed to download file from ${url}: ${resp.status} ${resp.statusText}`);
  }
  const blob = await resp.blob();
  const contentType = resp.headers.get("content-type") || "application/octet-stream";
  return { blob, contentType };
}

async function requestPresignedUrl(
  presignUrl: string,
  key: string,
  contentType: string,
  fetchFn: typeof fetch
): Promise<S3PresignResponse> {
  const body: S3PresignRequest = { Key: key, ContentType: contentType };
  const resp = await fetchFn(presignUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!resp.ok) {
    throw new Error(`S3 presign request failed: ${resp.status} ${resp.statusText} at ${presignUrl}`);
  }
  return (await resp.json()) as S3PresignResponse;
}

async function uploadToPresignedUrl(
  presignedUrl: string,
  blob: Blob,
  contentType: string,
  fetchFn: typeof fetch
): Promise<void> {
  const resp = await fetchFn(presignedUrl, {
    method: "PUT",
    headers: { "Content-Type": contentType },
    body: blob,
  });
  if (!resp.ok) {
    throw new Error(`S3 upload failed: ${resp.status} ${resp.statusText} at ${presignedUrl}`);
  }
}

function stripQueryParams(url: string): string {
  const u = new URL(url);
  u.search = "";
  return u.toString();
}

async function updateAirtableAttachment(
  baseId: string,
  tableId: string,
  recordId: string,
  apiKey: string,
  publicUrl: string,
  filename: string,
  fetchFn: typeof fetch
): Promise<AirtableUpdateResponse> {
  const url = `https://api.airtable.com/v0/${baseId}/${tableId}/${recordId}`;
  const body: AirtableUpdateRequest = {
    fields: {
      "File Attachment": [{ url: publicUrl, filename }],
    },
  };
  const resp = await fetchFn(url, {
    method: "PATCH",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  if (!resp.ok) {
    throw new Error(`Airtable update failed: ${resp.status} ${resp.statusText} at ${url}`);
  }
  return (await resp.json()) as AirtableUpdateResponse;
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  // Validate input
  if (!payload || typeof payload !== "object") {
    throw new Error("Invalid payload: expected object");
  }
  const typedPayload = payload as TypeformPayload;
  if (!typedPayload.form_response || !Array.isArray(typedPayload.form_response.answers)) {
    throw new Error("Invalid payload: missing form_response.answers");
  }

  const fetchFn = getFetch(config);

  // 1. Extract first file answer
  const fileAnswer = extractFirstFileAnswer(typedPayload);
  const fileUrl = fileAnswer.file_url!;

  // 2. Download file from Typeform
  const { blob, contentType: downloadedContentType } = await downloadFile(fileUrl, fetchFn);

  // 3. Derive Key and ContentType for S3
  const { key, contentType } = deriveKeyAndContentType(fileUrl);
  // Prefer downloaded content-type if available
  const finalContentType = downloadedContentType !== "application/octet-stream" ? downloadedContentType : contentType;

  // 4. Request presigned URL from S3 presign endpoint
  const presignResponse = await requestPresignedUrl(config.s3PresignUrl, key, finalContentType, fetchFn);
  const presignedUrl = presignResponse.url;

  // 5. Upload file to presigned URL
  await uploadToPresignedUrl(presignedUrl, blob, finalContentType, fetchFn);

  // 6. Derive public URL (strip query params)
  const publicUrl = stripQueryParams(presignedUrl);

  // 7. Resolve Airtable record ID
  const recordId = typeof config.airtableRecordId === "function"
    ? config.airtableRecordId(typedPayload)
    : config.airtableRecordId;

  // 8. Extract filename for Airtable
  const filename = key.split("/").pop() || "upload";

  // 9. Update Airtable attachment field
  const airtableResponse = await updateAirtableAttachment(
    config.airtableBaseId,
    config.airtableTableId,
    recordId,
    config.airtableApiKey,
    publicUrl,
    filename,
    fetchFn
  );

  const attachmentIds = airtableResponse.fields["File Attachment"].map((a) => a.id);

  return {
    s3PresignedUrl: presignedUrl,
    s3PublicUrl: publicUrl,
    airtableRecordId: airtableResponse.id,
    airtableAttachmentIds: attachmentIds,
  };
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { handle, ConnectorConfig, TypeformPayload } from "./connector";
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from "./fixtures";

describe("contract", () => {
  it("handles the documented example payload", async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      s3PresignUrl: "https://example.com/presign",
      airtableBaseId: "appXXXXXXXXXXXXXX",
      airtableTableId: "tblXXXXXXXXXXXXXX",
      airtableRecordId: "recXXXXXXXXXXXX",
      airtableApiKey: "test-api-key",
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.s3PublicUrl).toBeDefined();
    expect(result.airtableRecordId).toBeDefined();
  });
});

describe("handle", () => {
  let fetchMock: typeof fetch;
  let calls: RecordedCall[];
  let baseConfig: ConnectorConfig;

  beforeEach(() => {
    const { fetch, calls: c } = fakeFetch((req) => {
      // Default: reject unexpected
      return jsonResponse({ error: "unexpected" }, 404);
    });
    fetchMock = fetch;
    calls = c;
    baseConfig = {
      s3PresignUrl: "https://presign.example.com/presign",
      airtableBaseId: "appXXXXXXXXXXXXXX",
      airtableTableId: "tblXXXXXXXXXXXXXX",
      airtableRecordId: "recXXXXXXXXXXXX",
      airtableApiKey: "test-api-key",
      fetch: fetchMock,
    };
  });

  it("happy path: downloads file, gets presigned URL, uploads, updates Airtable", async () => {
    const { fetch, calls: c } = fakeFetch((req) => {
      // 1. Download file from Typeform
      if (req.method === "GET" && req.url.includes("api.typeform.com")) {
        return jsonResponse(new Blob(["fake-image-data"]), 200, {
          "Content-Type": "image/jpeg",
        });
      }
      // 2. S3 presign POST
      if (req.method === "POST" && req.url === baseConfig.s3PresignUrl) {
        const body = req.json as { Key: string; ContentType: string };
        expect(body.Key).toMatch(/^uploads\/\d+-arthur_team\.jpg$/);
        expect(body.ContentType).toBe("image/jpeg");
        return jsonResponse({
          url: "https://bucket.s3.amazonaws.com/uploads/123-arthur_team.jpg?sig=abc",
          fields: { key: "uploads/123-arthur_team.jpg", "Content-Type": "image/jpeg" },
        });
      }
      // 3. S3 PUT to presigned URL
      if (req.method === "PUT" && req.url.includes("bucket.s3.amazonaws.com")) {
        expect(req.headers.get("content-type")).toBe("image/jpeg");
        return new Response(null, { status: 200, statusText: "OK" });
      }
      // 4. Airtable PATCH
      if (req.method === "PATCH" && req.url.includes("api.airtable.com")) {
        expect(req.headers.get("authorization")).toBe("Bearer test-api-key");
        const body = req.json as { fields: { "File Attachment": Array<{ url: string }> } };
        expect(body.fields["File Attachment"][0].url).toBe("https://bucket.s3.amazonaws.com/uploads/123-arthur_team.jpg");
        return jsonResponse({
          id: "recXXXXXXXXXXXX",
          fields: {
            "File Attachment": [{ id: "att123", url: "https://dl.airtable.com/...", filename: "arthur_team.jpg" }],
          },
        });
      }
      return jsonResponse({ error: "not found" }, 404);
    });
    fetchMock = fetch;
    calls = c;

    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformPayload, { ...baseConfig, fetch: fetchMock });

    expect(result.s3PresignedUrl).toContain("sig=abc");
    expect(result.s3PublicUrl).toBe("https://bucket.s3.amazonaws.com/uploads/123-arthur_team.jpg");
    expect(result.airtableRecordId).toBe("recXXXXXXXXXXXX");
    expect(result.airtableAttachmentIds).toEqual(["att123"]);

    // Verify call sequence
    expect(calls[0].method).toBe("GET");
    expect(calls[0].url).toContain("api.typeform.com");
    expect(calls[1].method).toBe("POST");
    expect(calls[1].url).toBe(baseConfig.s3PresignUrl);
    expect(calls[2].method).toBe("PUT");
    expect(calls[2].url).toContain("bucket.s3.amazonaws.com");
    expect(calls[3].method).toBe("PATCH");
    expect(calls[3].url).toContain("api.airtable.com");
  });

  it("throws when no file_url answer in payload", async () => {
    const badPayload = {
      ...SOURCE_EXAMPLE,
      form_response: { ...SOURCE_EXAMPLE.form_response, answers: [{ type: "text", field: { id: "f1", type: "short_text" } }] },
    };
    await expect(handle(badPayload as unknown as TypeformPayload, baseConfig)).rejects.toThrow(
      "No file_url answer found"
    );
  });

  it("throws on non-2xx file download", async () => {
    const { fetch, calls: c } = fakeFetch((req) => {
      if (req.method === "GET" && req.url.includes("api.typeform.com")) {
        return jsonResponse({ error: "not found" }, 404);
      }
      return jsonResponse({ error: "unexpected" }, 404);
    });
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformPayload, { ...baseConfig, fetch })).rejects.toThrow(
      "Failed to download file"
    );
  });

  it("throws on non-2xx S3 presign response", async () => {
    const { fetch, calls: c } = fakeFetch((req) => {
      if (req.method === "GET" && req.url.includes("api.typeform.com")) {
        return jsonResponse(new Blob(["data"]), 200, { "Content-Type": "image/jpeg" });
      }
      if (req.method === "POST" && req.url === baseConfig.s3PresignUrl) {
        return jsonResponse({ error: "bad request" }, 400);
      }
      return jsonResponse({ error: "unexpected" }, 404);
    });
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformPayload, { ...baseConfig, fetch })).rejects.toThrow(
      "S3 presign request failed: 400"
    );
  });

  it("throws on non-2xx S3 upload", async () => {
    const { fetch, calls: c } = fakeFetch((req) => {
      if (req.method === "GET" && req.url.includes("api.typeform.com")) {
        return jsonResponse(new Blob(["data"]), 200, { "Content-Type": "image/jpeg" });
      }
      if (req.method === "POST" && req.url === baseConfig.s3PresignUrl) {
        return jsonResponse({ url: "https://bucket.s3.amazonaws.com/key?sig=abc", fields: {} });
      }
      if (req.method === "PUT" && req.url.includes("bucket.s3.amazonaws.com")) {
        return jsonResponse({ error: "forbidden" }, 403);
      }
      return jsonResponse({ error: "unexpected" }, 404);
    });
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformPayload, { ...baseConfig, fetch })).rejects.toThrow(
      "S3 upload failed: 403"
    );
  });

  it("throws on non-2xx Airtable update", async () => {
    const { fetch, calls: c } = fakeFetch((req) => {
      if (req.method === "GET" && req.url.includes("api.typeform.com")) {
        return jsonResponse(new Blob(["data"]), 200, { "Content-Type": "image/jpeg" });
      }
      if (req.method === "POST" && req.url === baseConfig.s3PresignUrl) {
        return jsonResponse({ url: "https://bucket.s3.amazonaws.com/key?sig=abc", fields: {} });
      }
      if (req.method === "PUT" && req.url.includes("bucket.s3.amazonaws.com")) {
        return new Response(null, { status: 200, statusText: "OK" });
      }
      if (req.method === "PATCH" && req.url.includes("api.airtable.com")) {
        return jsonResponse({ error: "unauthorized" }, 401);
      }
      return jsonResponse({ error: "unexpected" }, 404);
    });
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformPayload, { ...baseConfig, fetch })).rejects.toThrow(
      "Airtable update failed: 401"
    );
  });

  it("resolves record ID from function", async () => {
    const { fetch, calls: c } = fakeFetch((req) => {
      if (req.method === "GET" && req.url.includes("api.typeform.com")) {
        return jsonResponse(new Blob(["data"]), 200, { "Content-Type": "image/jpeg" });
      }
      if (req.method === "POST" && req.url === baseConfig.s3PresignUrl) {
        return jsonResponse({ url: "https://bucket.s3.amazonaws.com/key?sig=abc", fields: {} });
      }
      if (req.method === "PUT" && req.url.includes("bucket.s3.amazonaws.com")) {
        return new Response(null, { status: 200, statusText: "OK" });
      }
      if (req.method === "PATCH" && req.url.includes("api.airtable.com")) {
        expect(req.url).toContain("recFromFunction");
        return jsonResponse({
          id: "recFromFunction",
          fields: { "File Attachment": [{ id: "att1", url: "https://...", filename: "x.jpg" }] },
        });
      }
      return jsonResponse({ error: "unexpected" }, 404);
    });
    const config = {
      ...baseConfig,
      airtableRecordId: (payload: TypeformPayload) => `recFromFunction-${payload.form_response.token}`,
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformPayload, config);
    expect(result.airtableRecordId).toBe("recFromFunction");
  });
});

// Helper to create Response with custom headers for file download
function jsonResponse(body: unknown, status = 200, headers: Record<string, string> = {}): Response {
  const init: ResponseInit = {
    status,
    statusText: "",
    headers: { "Content-Type": "application/json", ...headers },
  };
  return new Response(status === 204 ? null : JSON.stringify(body), init);
}

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://www.typeform.com/developers/webhooks/example-payload/
// Source: https://docs.aws.amazon.com/AmazonS3/latest/userguide/PresignedUrlUploadObject.html
// Source: https://airtable.com/developers/web/api/update-record

/** Example payload of the source event, as documented. */
